"""Autogenerated private Kaggle entrypoint. Placeholders replaced offline."""
from __future__ import annotations
import base64
import io
import json
import os
import shutil
import subprocess
import sys
import traceback
import zipfile
from pathlib import Path

CONFIG_B64 = "__TW_SHORTS_JOB_B64__"
SOURCE_B64 = "__TW_SHORTS_SOURCE_B64__"
BASE = Path('/kaggle/working/tw_short_modules')
OUT = Path('/kaggle/working')


def main():
    # Standard HTTPS fallback avoids the Xet background-writer failure observed
    # on the actual first Kaggle run. It uses the same public model permissions.
    os.environ['HF_HUB_DISABLE_XET'] = '1'
    conf = json.loads(base64.b64decode(CONFIG_B64))
    package = base64.b64decode(SOURCE_B64)
    BASE.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(package)) as z:
        for member in z.infolist():
            rel = Path(member.filename)
            if rel.is_absolute() or '..' in rel.parts or not str(rel).startswith('studio/'):
                raise RuntimeError('Unsafe source module archive')
        z.extractall(BASE)
    sys.path.insert(0, str(BASE))
    phase = conf['phase']
    gpu_id = conf['gpu_id']
    if phase in {'image', 'voice'}:
        os.environ['CUDA_VISIBLE_DEVICES'] = str(gpu_id)
    if conf.get('install_deps') and phase in {'image', 'voice'}:
        packages = (['qwen-tts', 'soundfile'] if phase == 'voice' else
                    ['diffusers', 'transformers', 'accelerate', 'safetensors'])
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', *packages],
                       check=True, timeout=1200)
    # Optional explicit cache bootstrap. Defaults off: model weights should be
    # preattached via a private Kaggle model dataset to conserve GPU quota.
    model_root = Path(conf['model_path'])
    if not conf.get('bootstrap') and phase in {'image', 'voice'} and not model_root.exists():
        marker = 'model_index.json' if phase == 'image' else 'config.json'
        candidates = [p.parent.parent for p in Path('/kaggle/input').rglob(marker)
                      if p.parent.name == phase]
        if len(candidates) == 1:
            model_root = candidates[0]
    if conf.get('bootstrap') and phase in {'image', 'voice'}:
        from huggingface_hub import snapshot_download
        mapping = {'image': 'black-forest-labs/FLUX.2-klein-4B',
                   'voice': 'Qwen/Qwen3-TTS-12Hz-1.7B-CustomVoice'}
        dst = model_root / phase
        dst.mkdir(parents=True, exist_ok=True)
        if conf.get('preexisting_model_kernel'):
            marker = 'model_index.json' if phase == 'image' else 'config.json'
            previous = [p.parent for p in Path('/kaggle/input').rglob(marker) if p.parent.name == phase]
            if len(previous) == 1:
                # Copy only completed component files, omitting the failed
                # duplicate root checkpoint and incomplete download cache.
                for file in previous[0].rglob('*'):
                    rel = file.relative_to(previous[0])
                    if not file.is_file() or '.cache' in rel.parts or file.name.endswith('.incomplete'):
                        continue
                    if phase == 'image' and len(rel.parts) == 1 and file.suffix == '.safetensors':
                        continue
                    target = dst/rel
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(file, target)
        # FLUX publishes a duplicate 7.75GB single-file checkpoint at its root.
        # Diffusers needs only its component directories (~16GB); do not fill
        # the Notebook disk with a second copy of transformer weights.
        patterns = (['model_index.json', 'scheduler/*', 'text_encoder/*',
                     'tokenizer/*', 'transformer/*', 'vae/*', 'LICENSE.md']
                    if phase == 'image' else None)
        if conf.get('preexisting_model_kernel'):
            import fnmatch
            from huggingface_hub import HfApi
            files = HfApi().list_repo_files(mapping[phase])
            patterns = [name for name in files if (not patterns or any(fnmatch.fnmatch(name, p) for p in patterns))
                        and not (dst/name).is_file()]
        if patterns != []:
            snapshot_download(repo_id=mapping[phase], local_dir=str(dst), allow_patterns=patterns)
    if phase == 'voice' and not (model_root / 'alignment/config.json').is_file():
        # Optional forced alignment stays separate from narration synthesis.
        # A missing aligner is recorded instead of inventing word timestamps.
        try:
            from huggingface_hub import snapshot_download
            snapshot_download(repo_id='jonatasgrosman/wav2vec2-large-xlsr-53-russian',
                              local_dir=str(Path('/kaggle/working/private_models/alignment')),
                              allow_patterns=['*.json', '*.bin', '*.safetensors'])
        except Exception:
            pass
    from studio.kaggle_shorts_worker import main as worker
    source_path = Path(conf['source_path'])
    if not source_path.exists():
        matches = list(Path('/kaggle/input').rglob(source_path.name))
        if len(matches) == 1:
            source_path = matches[0]
        else:
            # Kaggle may unpack a Dataset ZIP before mounting it.
            projects = [p for p in Path('/kaggle/input').rglob('project.json')
                        if p.parent.name == conf['story'] and p.parent.parent.name == 'production_queue']
            if len(projects) == 1:
                source_path = projects[0].parent.parent.parent
    args = ['--source', str(source_path), '--story', conf['story'],
            '--phase', phase, '--models', str(model_root),
            '--work', '/kaggle/working/tw_private_project',
            '--out', '/kaggle/working', '--start', str(conf['first_scene']),
            '--count', str(conf['max_scenes']), '--time-budget', str(conf['budget_s']),
            '--gpu-id', str(gpu_id), '--speaker', conf['speaker']]
    if conf.get('recovery_path'):
        recovery = Path(conf['recovery_path'])
        if not recovery.exists():
            found = list(Path('/kaggle/input').rglob(recovery.name))
            if len(found) == 1:
                recovery = found[0]
        args += ['--recovery', str(recovery)]
    code = worker(args)
    if code != 0:
        raise SystemExit(code)


if __name__ == '__main__':
    try:
        main()
    except Exception as exc:
        receipt = OUT / 'two_worlds_kaggle_receipt.json'
        if not receipt.exists():
            gpu = {}
            try:
                import torch
                gpu = {'cuda': torch.cuda.is_available(), 'device_count': torch.cuda.device_count(),
                       'names': [torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())]}
            except Exception:
                pass
            receipt.write_text(json.dumps({'success': False, 'reviewed': False, 'published': False,
                'error_type': type(exc).__name__, 'message': str(exc),
                'traceback': traceback.format_exc(), 'gpu': gpu}, indent=2))
        raise
